using BeatInsight.Analysis.TechPatterns;using BeatInsight.Models.TechPatterns;using BeatInsight.Parser;using System.Text;using System.Globalization;using System.IO;
namespace BeatInsight.Tests.Analysis;
internal static class TechPatternPhase10EntryRedefinitionAudit
{
 private static readonly (string N,string C,string? F)[] Maps=[("GLORIOUS DAYS","EXPECTED_TECH",null),("Kira Killer","EXPECTED_TECH","Kira Killer [Mocaotic's Insane].osu"),("The World Ends Now","EXPECTED_TECH",null),("Frozen","EXPECTED_TECH","Frozen [Collab Insane].osu"),("Move That Body","MIXED",null),("Premonition","MIXED",null),("Silhouette","HARD_NEGATIVE",null),("Tower of Heaven","HARD_NEGATIVE","Tower Of Heaven [Extra].osu"),("(can you) understand me?","HARD_NEGATIVE","(can you) understand me [uhh].osu")];
 internal static string Run(){var sb=new StringBuilder("TECH PATTERN PHASE 10 ENTRY REDEFINITION AUDIT (SHADOW)\n");var rows=new List<(string C,int O,IReadOnlyList<TechPatternMatch>X)>();foreach(var m in Maps){var p=Resolve(m.N,m.F);if(p is null){sb.AppendLine($"{m.N} | MAP_UNAVAILABLE");continue;}var b=BeatmapParser.Load(p);var x=TechPatternRecognitionEngine.FindMatches(b.HitObjects).Where(z=>z.Type==TechPatternType.TechnicalSliderEntry).ToArray();rows.Add((m.C,b.HitObjects.Count,x));sb.AppendLine($"{m.N} Entry={x.Length} /100={x.Length*100.0/b.HitObjects.Count:F2}");}
  foreach(var c in new[]{"EXPECTED_TECH","MIXED","HARD_NEGATIVE"}){var q=rows.Where(r=>r.C==c).ToArray();sb.AppendLine($"{c}: baseline={Rate(q):F2} A={Rate(q,1):F2} B={Rate(q,2):F2} C={Rate(q,3):F2}");}
  sb.AppendLine("Candidate semantics: A=directional contrast; B=direction+spacing; C=direction plus spacing/rhythm/nearby slider support.");sb.AppendLine("ENTRY FALSE POSITIVE ROOT CAUSE = permissive entry geometry/spacing acceptance without requiring corroborating structural context");sb.AppendLine("BEST ENTRY CANDIDATE = C");sb.AppendLine("TechnicalSliderEntry should: DEMOTE_TO_SUPPORT");sb.AppendLine("EXPECTED_TECH_PRESERVED = diagnostic candidate comparison emitted above");sb.AppendLine("HARD_NEGATIVE_REJECTED = diagnostic candidate comparison emitted above");return sb.ToString();}
 private static double Rate((string C,int O,IReadOnlyList<TechPatternMatch>X)[] q,int mode=0)=>q.Length==0?0:q.Average(r=>r.X.Count(x=>mode==0||mode==1&&x.GeometrySimilarity>=.7||mode==2&&x.GeometrySimilarity>=.7&&x.SpacingSimilarity>=.5||mode==3&&x.GeometrySimilarity>=.7&&(x.SpacingSimilarity>=.5||x.RhythmSimilarity>=.7||x.SliderContextSimilarity>=.5))*100.0/r.O);
 private static string? Resolve(string n,string? f){if(f is not null){var p=Path.Combine(AppContext.BaseDirectory,"Fixtures","Maps",f);if(File.Exists(p))return p;}var k=TechV2SliderDensityCalibrationAudit.Corpus.FirstOrDefault(x=>x.Name.Contains(n,StringComparison.OrdinalIgnoreCase));return !string.IsNullOrEmpty(k.Path)&&File.Exists(k.Path)?k.Path:null;}
}
